alter table public.coaching_preferences add constraint coaching_preferences_check CHECK ((((max_demanding_days >= 1) AND (max_demanding_days <= 7)) AND (max_demanding_days <= weekly_training_days)));
alter table public.coaching_preferences add constraint coaching_preferences_check1 CHECK ((NOT (primary_focus_id = ANY (secondary_focus_ids))));
alter table public.coaching_preferences add constraint coaching_preferences_check2 CHECK ((NOT (primary_focus_id = ANY (maintenance_focus_ids))));
alter table public.coaching_preferences add constraint coaching_preferences_check3 CHECK ((NOT (secondary_focus_ids && maintenance_focus_ids)));
alter table public.coaching_preferences add constraint coaching_preferences_pkey PRIMARY KEY (person_id);
alter table public.coaching_preferences add constraint coaching_preferences_primary_focus_id_check CHECK ((btrim(primary_focus_id) <> ''::text));
alter table public.coaching_preferences add constraint coaching_preferences_secondary_focus_ids_check CHECK ((cardinality(secondary_focus_ids) <= 2));
alter table public.coaching_preferences add constraint coaching_preferences_weekly_minutes_check CHECK (((weekly_minutes >= 30) AND (weekly_minutes <= 1680)));
alter table public.coaching_preferences add constraint coaching_preferences_weekly_training_days_check CHECK (((weekly_training_days >= 1) AND (weekly_training_days <= 7)));
alter table public.coaching_recommendation_decisions add constraint coaching_recommendation_decis_person_id_week_start_recommen_key UNIQUE (person_id, week_start, recommendation_key);
alter table public.coaching_recommendation_decisions add constraint coaching_recommendation_decisions_action_details_check CHECK ((jsonb_typeof(action_details) = 'object'::text));
alter table public.coaching_recommendation_decisions add constraint coaching_recommendation_decisions_check CHECK (((original_date >= week_start) AND (original_date <= (week_start + 6))));
alter table public.coaching_recommendation_decisions add constraint coaching_recommendation_decisions_check1 CHECK (((proposed_date >= week_start) AND (proposed_date <= (week_start + 6))));
alter table public.coaching_recommendation_decisions add constraint coaching_recommendation_decisions_check2 CHECK (((chosen_date IS NULL) OR ((chosen_date >= week_start) AND (chosen_date <= (week_start + 6)))));
alter table public.coaching_recommendation_decisions add constraint coaching_recommendation_decisions_decision_check CHECK ((decision = ANY (ARRAY['accepted'::text, 'rejected'::text])));
